# Load all grids to track the task state
import os, glob, re

def load_grids():
    rlm_session_dir = os.environ.get('RLM_SESSION_DIR')
    if not rlm_session_dir:
        return {}

    sessions_file = os.path.join(os.path.dirname(rlm_session_dir), '..', 'sessions', os.path.basename(rlm_session_dir) + '.jsonl')
    print(f"Looking for sessions file: {sessions_file}")

    # Check if file exists
    if not os.path.exists(sessions_file):
        return {}

    G = {}
    content = open(sessions_file).read()

    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()
print("Loaded grids:", sorted(G.keys()))
